window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["data-drift-monitoring"]={"title":"数据漂移与持续监控：分布变化何时真的伤害系统","subtitle":"从 P(x)、P(y) 与 P(y|x)，到 PSI、延迟标签、代理指标、切片告警和安全响应。","thesis":"漂移检测比较基线与当前数据，但“分布不同”只是诊断信号，不等于质量已经下降，也不是自动重训命令。可靠闭环必须区分<b>输入、标签、概念和真实性能变化</b>，用延迟真值确认影响，并把告警连接到可回滚处置。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"退款原因从 50/30/20 变成 30/30/40","rule":"计算规则仍是逐桶求 (a−e)×ln(a/e) 后相加","steps":"不想要贡献约 0.102，尺寸为 0，质量贡献约 0.139","interpretation":"最大贡献提示质量问题占比翻倍"}}],"formulas":[{"id":"drift-psi","section":3,"formulaIndex":1,"symbols":[{"name":"PSI","meaning":"各离散桶分布变化贡献的总和","evidence":"输出各桶贡献和总漂移量 PSI"},{"name":"i","meaning":"正在比较的离散数据桶编号","evidence":"最后对桶 i 求和"},{"name":"a","meaning":"当前监控窗口中的桶比例","evidence":"当前窗口的比例 ai"},{"name":"e","meaning":"基线参照窗口中的桶比例","evidence":"基线比例 ei"},{"name":"ln","meaning":"用于比较比例倍数的自然对数函数","evidence":"自然对数 ln(ai/ei)"}]},{"id":"drift-slice-mixture","section":6,"formulaIndex":1,"symbols":[{"name":"Qoverall","meaning":"所有切片混合后的总体任务表现","evidence":"输出总体表现 Qoverall"},{"name":"k","meaning":"语言地区风险等切片的编号","evidence":"每个切片"},{"name":"w","meaning":"某个切片占全部流量的比例","evidence":"流量权重 wk"},{"name":"q","meaning":"某个切片内部的任务表现","evidence":"切片表现 qk"}]}],"termReviews":[{"section":1,"reviewedAt":"2026-07-27","terms":[{"name":"协变量漂移","meaning":"模型输入分布 P(x) 发生变化","purpose":"区分输入构成改变与正确答案规则改变","definitionEvidence":"P(x) 变表示输入构成变","purposeEvidence":"分类只定位变化发生在哪一层"},{"name":"概念漂移","meaning":"同样输入对应的正确标签关系 P(y|x) 发生变化","purpose":"识别旧决策规则在新政策下失效","definitionEvidence":"P(y|x) 变表示同样输入的正确答案规则变","purposeEvidence":"旧决策边界失效"}]},{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"PSI","meaning":"汇总离散桶当前比例与基线比例差异的指数","purpose":"提供可持续比较的分布变化效应信号","definitionEvidence":"输出各桶贡献和总漂移量 PSI","purposeEvidence":"作为需要调查的效应信号"},{"name":"高维","meaning":"一个样本同时由很多特征坐标表示的状态","purpose":"说明普通单变量距离不足以覆盖复杂嵌入变化","definitionEvidence":"高维嵌入","purposeEvidence":"可做分类器二样本检验或聚类监控"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"漂移分类区分协变量标签概念和真实性能四种变化。","evidence":"输出协变量、标签、概念或性能漂移的诊断"},"problem":{"answer":"它解决用户说法标签比例规则和实际错误是否是一回事。","evidence":"用户说法变了、退款资格规则变了、模型答错变多"},"inputOutput":{"answer":"输入历史与当前的 x、y、条件关系和指标，输出漂移类型。","evidence":"输入过去与当前的输入 x、标签 y、条件关系和任务指标"},"mechanism":{"answer":"分别比较 P(x)、P(y)、P(y|x) 和直接性能。","evidence":"P(x) 变表示输入构成变"},"interpretation":{"answer":"分类结果定位变化层级，不等于已经证明任务受损。","evidence":"只定位变化发生在哪一层"},"boundary":{"answer":"不能单凭输入分布变化断言模型质量下降。","evidence":"不能单凭输入变化断言模型已经变差"}},{"section":2,"definition":{"answer":"基线是带版本的历史分布或系统参照。","evidence":"输出训练集、最近稳定期、去年同期或控制组等带版本参照"},"problem":{"answer":"它解决当前流量究竟应和哪个时期或版本比较。","evidence":"当前流量应该和训练集、上周还是去年同期比较"},"inputOutput":{"answer":"输入问题版本季节与窗口，输出合适的参照。","evidence":"输入监控问题、应用与模型版本、季节性和时间窗口"},"mechanism":{"answer":"组合快速慢速季节和控制基线并核对版本。","evidence":"快速窗口发现突变，慢速窗口观察趋势"},"interpretation":{"answer":"不同基线回答不同问题，越线含义必须随参照解释。","evidence":"比较前先确认提示、索引、政策和埋点版本一致"},"boundary":{"answer":"滚动基线可能跟随变化并吞掉慢性漂移。","evidence":"滚动基线可能吞掉慢性漂移"}},{"section":3,"definition":{"answer":"PSI 汇总同一组离散桶当前与基线比例的变化。","evidence":"输出各桶贡献和总漂移量 PSI"},"problem":{"answer":"它把多个类别比例差异压成可比较的漂移信号。","evidence":"词类比例差多少，怎样压成一个可比较数"},"inputOutput":{"answer":"输入 ai 与 ei，输出桶贡献和 PSI 总值。","evidence":"输入同一组离散桶在当前窗口的比例 ai 与基线比例 ei"},"mechanism":{"answer":"逐桶求差乘对数比例并对 i 求和。","evidence":"逐桶计算差值 ai−ei，再乘自然对数"},"interpretation":{"answer":"零表示分桶分布相同，较高表示差异较大。","evidence":"分布相同时结果为零"},"boundary":{"answer":"分桶平滑样本量会改变数值，不能自动触发重训。","evidence":"不能作为自动重训结论"}},{"section":4,"definition":{"answer":"PSI 手算案例分解退款原因各桶对总漂移的贡献。","evidence":"输出每桶 PSI 贡献、总和及业务解释"},"problem":{"answer":"它找出整体数值主要由哪个业务类别推动。","evidence":"漂移主要来自哪里"},"inputOutput":{"answer":"输入退款原因的基线和当前比例，输出贡献与总和。","evidence":"输入“不想要、尺寸、质量”等桶的基线 e 与当前 a"},"mechanism":{"answer":"按同一公式逐桶计算并把贡献相加。","evidence":"三项和约 0.241"},"interpretation":{"answer":"质量桶贡献最大提示该原因占比翻倍值得调查。","evidence":"最大贡献提示质量问题占比翻倍"},"boundary":{"answer":"完整分桶和平滑不同会改总值，仍需政策和真值确认。","evidence":"仍需核对 45 天政策和 14 天成熟标签"}},{"section":5,"definition":{"answer":"延迟标签监控把即时代理与稍后成熟的业务真值连接。","evidence":"输出早期预警和成熟性能"},"problem":{"answer":"它解决最终退款正确性需十四天才能知道时如何预警。","evidence":"退款最终是否正确要 14 天才知道"},"inputOutput":{"answer":"输入即时代理和回填结果，输出预警与真实性能。","evidence":"输入检索空结果、重问、人工接管、置信等即时代理"},"mechanism":{"answer":"保存事件切片版本，标签成熟后重算质量和校准。","evidence":"标签成熟后再计算准确率、风险、校准和覆盖"},"interpretation":{"answer":"代理只提出假设，必须由最终业务状态校验。","evidence":"代理只能提出待验证假设"},"boundary":{"answer":"未成熟样本不能因为尚无失败而提前记为正确。","evidence":"不能提前记为正确"}},{"section":6,"definition":{"answer":"切片监控同时观察总体加权表现和群体内部表现。","evidence":"输出总体表现 Qoverall 与各切片区间"},"problem":{"answer":"它解决总体稳定掩盖少数高风险群体退化的问题。","evidence":"权重变化能掩盖少数群体退化"},"inputOutput":{"answer":"输入 wk、qk、样本量和风险，输出总体与切片区间。","evidence":"输入每个切片的流量权重 wk、切片表现 qk、样本量和风险等级"},"mechanism":{"answer":"按权重求总体并分别比较构成与切片内变化。","evidence":"同时比较构成变化与切片内变化"},"interpretation":{"answer":"总体变化可能仅来自流量构成而非任何切片变差。","evidence":"总体是各切片表现的加权和"},"boundary":{"answer":"小样本需区间，高损失切片不能只等总体显著。","evidence":"高损失切片可使用事件门槛"}},{"section":7,"definition":{"answer":"调查树是从漂移告警到验证根因和选择修复的流程。","evidence":"输出经验证的根因候选和修复选择"},"problem":{"answer":"它避免把任何统计变化直接等同于需要自动重训。","evidence":"检测到漂移后是否应该自动重训"},"inputOutput":{"answer":"输入告警版本和切片证据，输出根因候选与动作。","evidence":"输入一次漂移告警、版本与切片证据"},"mechanism":{"answer":"先验信号再查切片外因，回放后选择最小修复。","evidence":"先排除埋点时区采样等信号错误"},"interpretation":{"answer":"只有对照回放支持的候选才能作为可行动根因。","evidence":"在新旧系统和冻结工具响应上回放"},"boundary":{"answer":"异常生产输入须审核，不能自动写回训练集。","evidence":"不能自动回流训练"}},{"section":8,"definition":{"answer":"告警手册把监控信号连接到负责人和允许的处置动作。","evidence":"输出观察、呼叫、阻断、回滚或转人工处置"},"problem":{"answer":"它解决红灯太多却无人知道何时做什么的问题。","evidence":"每天几十个红灯没人处理"},"inputOutput":{"answer":"输入阈值预算负责人动作，输出分级响应。","evidence":"输入基线、窗口、最小样本、效应阈值、错误预算、负责人和允许动作"},"mechanism":{"answer":"普通噪声看连续窗口，安全事件可即时阻断。","evidence":"安全事件可立即阻断"},"interpretation":{"answer":"告警表示规则越线，需要调查或止损而非宣告根因。","evidence":"恢复后记录真阳性和处置收益"},"boundary":{"answer":"没告警只覆盖已选特征，不能证明系统没有退化。","evidence":"不证明系统没有退化"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分四类漂移；手算 PSI 并理解统计边界；设计无标签早期预警；把漂移告警转成调查与发布闭环。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先把四种变化分开<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">用户说法变了、退款资格规则变了、模型答错变多，是同一件事吗？</p><p>协变量漂移是输入分布 P(x) 变化，例如“破损”被新口语“翻车货”替代；标签漂移是 P(y) 变化，例如节日后退款请求中合格订单比例上升；概念漂移是 P(y|x) 变化，例如政策把质量问题窗口从 30 天延到 45 天；性能漂移是正确率、风险或校准实际下降。</p><p>P(x) 变化不必伤害模型：用户从 iOS 换 Android，而任务只看订单日期时，设备漂移可能无关。P(y|x) 变化即使 P(x) 外观稳定也会让旧决策边界失效，因此仅监控输入字段永远不够。</p><div class=\"dd-note\"><b>因果顺序：</b>先观察“什么变了”，再验证“是否影响任务”，最后判断“该修数据、规则、模型还是管道”。</div><p>漂移分类输入过去与当前的输入 x、标签 y、条件关系和任务指标，输出协变量、标签、概念或性能漂移的诊断。P(x) 变表示输入构成变，P(y) 变表示标签比例变，P(y|x) 变表示同样输入的正确答案规则变；最后还要直接观察性能。分类只定位变化发生在哪一层，不能单凭输入变化断言模型已经变差。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>基线不是永恒真理，而是带版本的参照<span class=\"dd-badge eng\">设计</span></h2><p class=\"dd-lead\">当前流量应该和训练集、上周还是去年同期比较？</p><p>不同问题需要不同基线：训练/评测分布回答是否离开能力证据；最近稳定窗口回答是否突然异常；去年同期处理季节性。每个基线要绑定应用、模型、提示、索引、政策和埋点版本，否则正常发布也会被误报成漂移。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>参照</th><th>适合发现</th><th>主要误判</th></tr></thead><tbody><tr><td>训练/冻结评测集</td><td>能力证据外推风险</td><td>本来就不代表生产</td></tr><tr><td>最近稳定窗口</td><td>突发管道或攻击</td><td>慢性漂移被基线追随</td></tr><tr><td>季节同期</td><td>节假日与周期模式</td><td>产品和政策已变</td></tr><tr><td>控制组/旧版本</td><td>新发布的增量影响</td><td>分流不随机或互相污染</td></tr></tbody></table></div><p>窗口太短噪声大，太长会稀释突变。实践常同时维护快速告警窗口和慢速趋势窗口。</p><p>基线设计输入监控问题、应用与模型版本、季节性和时间窗口，输出训练集、最近稳定期、去年同期或控制组等带版本参照。快速窗口发现突变，慢速窗口观察趋势，季节同期减少周期误报；比较前先确认提示、索引、政策和埋点版本一致。会追随当前流量的滚动基线可能吞掉慢性漂移。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>从类别分布到 PSI<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">基线和当前窗口的词类比例差多少，怎样压成一个可比较数？</p><p>对离散桶，Population Stability Index 把每桶当前比例 aᵢ 与基线比例 eᵢ 的差乘以对数比，再求和。它对称地在分布相同时为 0，差距越大通常越高。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"总体稳定性指数\"><mi>PSI</mi><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><mrow><mo>(</mo><msub><mi>a</mi><mi>i</mi></msub><mo>−</mo><msub><mi>e</mi><mi>i</mi></msub><mo>)</mo></mrow><mo>×</mo><mi>ln</mi><mo>(</mo><mfrac><msub><mi>a</mi><mi>i</mi></msub><msub><mi>e</mi><mi>i</mi></msub></mfrac><mo>)</mo></math></div><p>PSI 依赖分桶，零频需要平滑，行业常用阈值只是经验规则，不是统计定律。连续变量还可用 KS；类别可用卡方；概率分布可用 JS/KL；高维嵌入可做分类器二样本检验或聚类监控。任何距离都必须连接任务影响。</p><div class=\"dd-note warn\"><b>大样本陷阱：</b>数百万请求下极小差异也会统计显著；告警应同时要求效应量、持续时间和业务相关性。</div><p>PSI 输入同一组离散桶在当前窗口的比例 ai 与基线比例 ei，输出各桶贡献和总漂移量 PSI。逐桶计算差值 ai−ei，再乘自然对数 ln(ai/ei)，最后对桶 i 求和；分布相同时结果为零。数值受分桶、平滑和样本量影响，只能作为需要调查的效应信号，不能作为自动重训结论。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：新政策上线后的 PSI 手算<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">退款原因从 50/30/20 变成 30/30/40，漂移主要来自哪里？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 255\" role=\"img\" aria-label=\"退款原因基线与当前比例及从漂移告警到延迟真值确认的流程\"><rect x=\"28\" y=\"38\" width=\"258\" height=\"174\" rx=\"10\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"157\" y=\"62\" text-anchor=\"middle\" class=\"svg-t\">退款原因分布</text><text x=\"78\" y=\"190\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不想要</text><rect x=\"55\" y=\"100\" width=\"22\" height=\"75\" fill=\"#6b8cbe\"/><rect x=\"82\" y=\"130\" width=\"22\" height=\"45\" fill=\"#d3a05a\"/><text x=\"158\" y=\"190\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">尺寸</text><rect x=\"135\" y=\"130\" width=\"22\" height=\"45\" fill=\"#6b8cbe\"/><rect x=\"162\" y=\"130\" width=\"22\" height=\"45\" fill=\"#d3a05a\"/><text x=\"238\" y=\"190\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">质量</text><rect x=\"215\" y=\"145\" width=\"22\" height=\"30\" fill=\"#6b8cbe\"/><rect x=\"242\" y=\"115\" width=\"22\" height=\"60\" fill=\"#d3a05a\"/><text x=\"110\" y=\"82\" class=\"svg-t\" font-size=\"11\">蓝=基线 50/30/20　黄=当前 30/30/40</text><path d=\"M286,125 L353,125\" stroke=\"#6b7484\"/><polygon points=\"353,125 344,120 344,130\" fill=\"#6b7484\"/><rect x=\"355\" y=\"75\" width=\"144\" height=\"98\" rx=\"9\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"427\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">PSI≈0.358</text><text x=\"427\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">质量问题贡献最大</text><text x=\"427\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">只是调查信号</text><text x=\"427\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不是重训命令</text><path d=\"M499,125 L553,125\" stroke=\"#6b7484\"/><polygon points=\"553,125 544,120 544,130\" fill=\"#6b7484\"/><rect x=\"555\" y=\"75\" width=\"122\" height=\"98\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"616\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">按切片回放</text><text x=\"616\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">政策版本核验</text><text x=\"616\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">14 天标签回填</text><text x=\"616\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">确认性能影响</text></svg><figcaption>图 1　统计量只告诉我们分布变了；政策与成熟标签决定这次变化是否伤害系统。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>桶</th><th>e 基线</th><th>a 当前</th><th>(a−e)ln(a/e)</th></tr></thead><tbody><tr><td>不想要</td><td>.50</td><td>.30</td><td>(−.20)ln(.6)=.102</td></tr><tr><td>尺寸</td><td>.30</td><td>.30</td><td>0</td></tr><tr><td>质量</td><td>.20</td><td>.40</td><td>.20ln(2)=.139</td></tr></tbody></table></div><p>三项按公式约 0.241；若另有“其他”桶从 0.10 到 0.04，其贡献约 0.055，总值随完整分桶约 0.296。图中 0.358 用另一平滑/分桶示意，正好说明 PSI 数值不能脱离分桶复现。真正重要的是“质量问题占比翻倍”，而新 45 天政策可能令旧资格逻辑漏判。</p><p>手算案例输入“不想要、尺寸、质量”等桶的基线 e 与当前 a，输出每桶 PSI 贡献、总和及业务解释。计算规则仍是逐桶求 (a−e)×ln(a/e) 后相加：不想要贡献约 0.102，尺寸为 0，质量贡献约 0.139，三项和约 0.241；不同“其他”桶和平滑会改变总值。最大贡献提示质量问题占比翻倍，但仍需核对 45 天政策和 14 天成熟标签。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>没有真值时只能用代理，不可把代理当结论<span class=\"dd-badge eng\">延迟标签</span></h2><p class=\"dd-lead\">退款最终是否正确要 14 天才知道，今天怎样预警？</p><p>可先看输入新词率、检索空结果、低置信、拒答、用户重问、人工接管、工具错误、规则冲突和版本变化。这些是早期信号：接管率上升可能代表模型变差，也可能是新审核政策更严格；置信稳定也可能是模型在新分布上自信地错。</p><p>建立标签成熟队列：每个预测保存事件时间、切片和版本；14 天后回填退款是否被撤销、人工是否改判，再计算准确率、风险、校准与选择性覆盖。避免用“尚未发生失败”把未成熟样本记为正确。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>早期代理</th><th>可能根因</th><th>需等待的真值</th></tr></thead><tbody><tr><td>检索空结果↑</td><td>新词、索引故障、权限过滤</td><td>必要政策证据是否存在</td></tr><tr><td>转人工↑</td><td>难度、阈值或容量变化</td><td>人工最终改判及原因</td></tr><tr><td>用户重问↑</td><td>回答不清或界面变化</td><td>任务是否最终解决</td></tr><tr><td>置信分布稳定</td><td>可能无变化，也可能失准</td><td>按置信桶实际正确率</td></tr></tbody></table></div><p>延迟标签监控输入检索空结果、重问、人工接管、置信等即时代理，以及稍后回填的真实业务结果，输出早期预警和成熟性能。预测时保存事件时间、切片与版本，标签成熟后再计算准确率、风险、校准和覆盖；代理只能提出待验证假设。尚未观察到最终失败的样本不能提前记为正确。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>平均稳定会掩盖局部伤害<span class=\"dd-badge math\">切片</span></h2><p class=\"dd-lead\">总体准确率仍是 90%，为什么中文质量问题用户可能已经从 85% 掉到 55%？</p><p>如果该切片只占 3%，其他流量从 90.2% 微升到 91.1%，总体仍可能看似稳定。必须按语言、地区、产品、渠道、长度、风险和政策版本切片，同时控制多重比较与小样本噪声。</p><p>对小切片报告分子/分母和区间，使用较长窗口或层级收缩；不要因 2/3 失败立刻永久告警，也不能因样本少忽略高损失群体。高风险切片可用事件计数与零容忍门槛，而不是等待总体显著性。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"总体表现是各切片表现的加权和\"><mi>Qoverall</mi><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>w</mi><mi>k</mi></msub><mo>×</mo><msub><mi>q</mi><mi>k</mi></msub></math></div><p>因此要同时区分“构成变化”和“切片内性能变化”。前者可能只是更多困难案例进入，后者才更直接指向模型或系统在同类任务上退化。</p><p>切片监控输入每个切片的流量权重 wk、切片表现 qk、样本量和风险等级，输出总体表现 Qoverall 与各切片区间。总体是各切片表现的加权和，所以权重变化能掩盖少数群体退化；同时比较构成变化与切片内变化。小样本需报告分子分母和区间，高损失切片可使用事件门槛而非等待总体显著。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>漂移告警后的调查树<span class=\"dd-badge eng\">响应</span></h2><p class=\"dd-lead\">为什么“检测到漂移→自动重训”是危险捷径？</p><ol class=\"dd-steps\"><li><b>验证信号：</b>埋点、解析、时区、去重、采样和基线是否变化。</li><li><b>定位切片：</b>哪些输入、版本、地区和风险贡献最大。</li><li><b>检查外因：</b>政策、产品入口、营销活动、攻击或上游服务是否改变。</li><li><b>回放评测：</b>在新旧系统、oracle 证据和冻结工具响应上比较。</li><li><b>选择修复：</b>修埋点、更新规则/检索/提示、收紧阈值，最后才考虑训练。</li><li><b>渐进发布：</b>影子与金丝雀验证，保留旧版本回滚。</li></ol><div class=\"dd-note warn\"><b>投毒风险：</b>把异常生产输入自动加入训练，攻击者可能借漂移通道改变模型。样本必须去标识、去重、审核来源和标签。</div><p>调查树输入一次漂移告警、版本与切片证据，输出经验证的根因候选和修复选择。它解决检测到漂移后是否应该自动重训的问题。先排除埋点时区采样等信号错误，再定位贡献切片、检查政策产品攻击等外因，并在新旧系统和冻结工具响应上回放；之后才选规则、检索、提示或训练修复。异常生产输入必须审核，不能自动回流训练。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>告警应连接错误预算和可执行手册<span class=\"dd-badge eng\">运维</span></h2><p class=\"dd-lead\">每天几十个红灯没人处理，监控系统哪里失败了？</p><p>每项监控写明基线、窗口、最小样本、效应阈值、严重度、负责人、诊断链接和允许动作。单点越线可观察，连续多个窗口或快速耗尽错误预算才呼叫；安全事件则可即时阻断。</p><p>处置可能是冻结自动退款、提高转人工阈值、回滚索引或切换旧政策，而不一定重训。恢复后更新评测集和基线，但保留旧基线用于识别慢性漂移；记录告警是否真阳性和处置收益，定期删除无行动价值的噪声指标。</p><div class=\"dd-note warn\"><b>没有检测到漂移不等于没有退化。</b>　你只监控了选定特征；遗漏变量、标签错误和模型内部变化仍可能造成伤害。</div><p>告警运行手册输入基线、窗口、最小样本、效应阈值、错误预算、负责人和允许动作，输出观察、呼叫、阻断、回滚或转人工处置。连续窗口或快速消耗错误预算才处理普通噪声，安全事件可立即阻断；恢复后记录真阳性和处置收益。未检测到漂移只表示已监控特征未越线，不证明系统没有退化。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">漂移监控的价值不是提前宣布根因，而是缩短从变化到可信处置的路径。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>输入变了，模型一定坏了</td><td>P(x) 变化需用任务标签验证影响</td></tr><tr><td>PSI 超过固定值就重训</td><td>阈值依赖分桶、样本和业务，先调查</td></tr><tr><td>置信稳定说明质量稳定</td><td>新分布可能破坏校准而分数外观不变</td></tr><tr><td>总体指标足够</td><td>少数、高风险和新政策切片可能被平均掩盖</td></tr><tr><td>生产数据自动回流最及时</td><td>会带入错标、选择偏差、隐私和投毒</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>概率分布、模型评测、应用评测、可观测性</td></tr><tr><td><b>本页核心</b></td><td>协变量/标签/概念/性能漂移、PSI、延迟真值、切片告警</td></tr><tr><td>修复</td><td>不确定性校准、训练数据治理、模型选择与部署</td></tr><tr><td>风险</td><td>数据投毒、人在回路、隐私治理和事件响应</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>冻结带版本的多重基线</li><li>持续采集脱敏特征与代理</li><li>按窗口/切片量化变化</li><li>验证埋点并定位贡献来源</li><li>等待成熟标签确认任务影响</li><li>渐进修复并更新评测与基线</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>P(y|x) 变化叫什么？</li><li>PSI 高为什么不能直接触发重训？</li><li>未成熟标签为何不能记为正确？</li><li>总体稳定为何还要切片？</li><li>生产回流为何需审核？</li><li>假设“数据漂移与持续监控：分布变化何时真的伤害系统”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“数据漂移与持续监控：分布变化何时真的伤害系统”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>概念漂移，它可在输入外观稳定时改变正确决策。</li><li>它只表明选定分桶分布不同，还可能来自埋点、政策、季节或无关变量。</li><li>结果尚未观察，会系统性低估延迟失败。</li><li>小群体退化可被权重变化或其他切片提升抵消。</li><li>避免选择偏差、错标、隐私泄漏和攻击者投毒。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1810.11953\" target=\"_blank\" rel=\"noopener\">Failing Loudly: An Empirical Study of Methods for Detecting Dataset Shift</a>：无标签数据集漂移检测</li><li><a href=\"https://arxiv.org/abs/2004.05785\" target=\"_blank\" rel=\"noopener\">Learning under Concept Drift: A Review</a>：概念漂移定义与方法</li><li><a href=\"https://papers.nips.cc/paper/5656-hidden-technical-debt-in-machine-learning-systems\" target=\"_blank\" rel=\"noopener\">Hidden Technical Debt in Machine Learning Systems</a>：反馈环与监控债务</li><li><a href=\"https://airc.nist.gov/airmf-resources/airmf/5-sec-core/\" target=\"_blank\" rel=\"noopener\">NIST AI RMF Core</a>：部署监测、测量与响应</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
